import{_ as a,o as l,c as t,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Code Walkthroughs: SeaStore","description":"","frontmatter":{"title":"Ceph Code Walkthroughs: SeaStore","date":"2023-07-03T00:00:00.000Z","updated":"2023-07-04T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH算法","高可用性","可伸缩性","对象存储","块存储","文件系统存储","一致性","去中心化","性能","Bluestore","BlueFS","RocksDB","OSD","MON","MDS","PG","RADOS","librados","libcephfs","cephfs","rbd","radosgw","RGW","RESTful API","认证","授权","加密","纠错码","复制","快照","克隆","瘦化配置","iSCSI","Fibre Channel","NFS","CIFS","POSIX","监控","仪表板","管理","编排","自动化","集成","容器化","Kubernetes","Docker","虚拟化","云计算","AWS","Azure","Google Cloud","混合云","多云","存储集群","节点","硬盘","SSD","HDD","JBOD","SAN","NAS","网络","拓扑","失败域","恢复","弹性","负载均衡","缓存","压缩","去重","分层","性能调优","基准测试","测试","验证"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_Code_Walkthroughs_-_SeaStore.md","filePath":"posts/2023/Ceph_Code_Walkthroughs_-_SeaStore.md","lastUpdated":1780459816000}'),r={name:"posts/2023/Ceph_Code_Walkthroughs_-_SeaStore.md"};function i(s,e,n,h,u,d){return l(),t("div",null,[...e[0]||(e[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-ceph存储系统中的新对象存储实现-c-store" tabindex="-1">会议主题：Ceph存储系统中的新对象存储实现 - c-store <a class="header-anchor" href="#会议主题-ceph存储系统中的新对象存储实现-c-store" aria-label="Permalink to &quot;会议主题：Ceph存储系统中的新对象存储实现 - c-store&quot;">​</a></h4><h4 id="会议时间-具体时间" tabindex="-1">会议时间：[具体时间] <a class="header-anchor" href="#会议时间-具体时间" aria-label="Permalink to &quot;会议时间：[具体时间]&quot;">​</a></h4><h4 id="参会人员-参会人员名单" tabindex="-1">参会人员：[参会人员名单] <a class="header-anchor" href="#参会人员-参会人员名单" aria-label="Permalink to &quot;参会人员：[参会人员名单]&quot;">​</a></h4><h4 id="会议内容总结" tabindex="-1">会议内容总结： <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结：&quot;">​</a></h4><p>本次会议深入探讨了Ceph存储系统中新对象存储实现c-store的设计和架构。以下为会议关键点：</p><ol><li><p><strong>c-store简介</strong>：</p><ul><li>c-store是为Crimson的线程和回调模型设计的对象存储实现。</li><li>目标是避免CPU密集型的元数据设计，提供灵活的架构，支持多种存储配置和工作负载。</li></ul></li><li><p><strong>设计目标</strong>：</p><ul><li>支持多种存储配置，包括QLC或ZNS闪存设备、硬盘以及高性能的NVMe设备。</li><li>实现内部层级管理，减轻集群设置的设计参数压力，允许更好地结合不同类型的存储池。</li></ul></li><li><p><strong>对象存储接口</strong>：</p><ul><li>对象存储是OSD与其本地存储通信的接口，具有事务性和平面对象命名空间特性。</li><li>支持对象克隆和RADOS快照。</li></ul></li><li><p><strong>内部元数据结构</strong>：</p><ul><li>包括LBA B树和back ref B树，通过逻辑偏移量进行管理，允许透明地移动数据块。</li></ul></li><li><p><strong>日志记录机制</strong>：</p><ul><li>在块级别上进行一致性处理，记录包括Delta和新的逻辑及物理块的完整记录。</li></ul></li><li><p><strong>架构组件</strong>：</p><ul><li>主要组件包括onode manager、omap manager、object data handler、transaction manager等，处理逻辑地址并管理元数据结构。</li></ul></li><li><p><strong>缓存管理</strong>：</p><ul><li>c-store包含一个缓存，用于性能优化和确保事务进行中的正确性。</li></ul></li><li><p><strong>设备管理</strong>：</p><ul><li>通过extent placement manager管理不同性能级别的设备，支持垃圾收集和层级管理。</li></ul></li><li><p><strong>未来工作</strong>：</p><ul><li>优化多核支持，测试随机读写工作负载，并改进内部元数据结构。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>c-store已集成到Crimson实验版本中，未来六个月内将优先考虑其稳定性和性能优化。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>测试c-store在不同工作负载下的表现，特别是RBD的随机读写性能。</li><li>收集社区反馈，特别是关于内部元数据结构的改进建议。</li><li>完成多核支持的开发，并确保c-store的稳定性和可靠性。</li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><ul><li>感谢所有参会人员的参与和贡献，期待社区的进一步反馈和支持。</li></ul>',13)])])}const _=a(r,[["render",i]]);export{c as __pageData,_ as default};
